477	// =====================================================================
478	//  STAGE BODIES — each is CTA-cooperative with the owner-computes
479	//  determinism rule (one thread fully reduces each output element).

980	//  Runs S0..S5 for ONE tensor (task id `t`) the calling CTA owns. All
981	//  intermediates live in this CTA's workspace slice. __syncthreads()
982	//  separates data-dependent stages WITHIN the CTA (the only coupling is
983	//  this CTA's own rows; no cross-CTA dependence, hence no grid barrier).
984	// =====================================================================
985	template <typename Dims, typename ParamT, typename GradT>
986	__device__ void sg2_meta_stages(
987	    const SG2SmemWeights<Dims>& w,
988	    int tid,                            // task (tensor) index
989	    const SG2State& st,
990	    const SG2Scalars& sc,
991	    ParamT* __restrict__ param_base,    // packed params [total]
992	    const GradT* __restrict__ grad_base,// packed grads  [total]
993	    const float* __restrict__ sharp_base,// packed sharpness [total]
994	    float* __restrict__ ws_base) {      // this CTA's workspace slice
995	    constexpr int d = Dims::d_model;
996	    const int N = st.n[tid];
997	    if (N == 0) return;
998	    const int64_t off = st.row_off[tid];
999	    const int Nc = (N + Dims::csa_compress - 1) / Dims::csa_compress;
1000	    const int Nh = (N + Dims::hca_compress - 1) / Dims::hca_compress;
1001	    const int topk = (Dims::csa_topk < Nc) ? Dims::csa_topk : Nc;
1002	    const int topk1 = (topk > 0) ? topk : 1;
1003	
1004	    // Tensor-slice pointers.
1005	    ParamT* param = param_base + off;
1006	    const GradT* grad = grad_base + off;
1007	    const float* sharp = sharp_base + off;
1008	    float* exp_avg = st.exp_avg + off;
1009	    float* exp_avg_sq = st.exp_avg_sq + off;
1010	    float* mu = st.mu + off;
1011	    float* slow = st.slow + off;
1012	    float* gru_state = st.gru_state + off * Dims::gru_hidden;
1013	    const int* perm = st.perm + off;
1014	    const int* unsort = st.unsort + off;
1015	
1016	    // Workspace (carved for Nmax, used for this N).
1017	    SG2Work<Dims> ws = sg2_carve_ws<Dims>(ws_base, /*Nmax=*/N /*carved per tensor*/);
1018	    // NOTE: we carve at exactly N (not Nmax) so the buffers are tightly packed
1019	    // for THIS tensor — valid because ws_stride(Nmax) >= ws_stride(N). The host
1020	    // sizes the slice for Nmax; carving at N keeps the working set contiguous.
1021	
1022	    // S0: input projection + gather sorted features.
1023	    sg2_stage_input_proj_sorted<Dims>(w, grad, sharp, perm, ws.x_sorted, N);
1024	    __syncthreads();
1025	
1026	    // Build g_sorted / s_sorted (per-row scalars in sorted order) into the front
1027	    // of qI's buffer is unsafe (qI needed later); instead recompute from grad on
1028	    // the fly where needed (GRU/PEER read g_sorted[r] = grad[perm[r]]). To keep a
1029	    // single source we materialize them into new_gru-adjacent scratch: reuse the
1030	    // tail of expert_out? Too small. Simplest deterministic choice: store into
1031	    // dedicated columns we already have — qI is [N,rank] (rank>=4), so stash
1032	    // g_sorted in concat[:,0] / s_sorted in concat[:,1] BEFORE concat is used by
1033	    // attention? concat is used by out-proj. To avoid any aliasing we compute
1034	    // g_sorted/s_sorted lazily inside GRU/PEER via grad[perm[r]]. (No buffer.)
1035	
1036	    // S1: CSA context.
1037	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_q_W, ws.q, N);             // q
1038	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_k_W, w.csa_compress_w, ws.c_k, N, Nc);
1039	    sg2_stage_compress<Dims, /*IsCsa=*/true>(ws.x_sorted, w.csa_v_W, w.csa_compress_w, ws.c_v, N, Nc);
1040	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_k_W, ws.win_k, N);         // window k
1041	    sg2_stage_project<Dims>(ws.x_sorted, w.csa_v_W, ws.win_v, N);         // window v
1042	    sg2_stage_indexer_q<Dims>(ws.x_sorted, w.csa_idx_DQ, ws.qI, N);
1043	    sg2_stage_indexer_k<Dims>(ws.x_sorted, w.csa_idx_K, w.csa_compress_w, ws.kI, N, Nc);
1044	    __syncthreads();
1045	    sg2_stage_topk<Dims>(ws.qI, ws.kI, ws.sel, N, Nc, topk1);
1046	    __syncthreads();
1047	    sg2_stage_csa_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1048	                                  ws.sel, ws.concat, N, Nc, topk1);
1049	    __syncthreads();
1050	    sg2_stage_out_proj<Dims>(ws.concat, w.csa_out_W, ws.csa_ctx, N);
1051	    __syncthreads();
1052	
1053	    // S2: HCA context (reuse q/c_k/c_v/win_k/win_v/concat scratch).
1054	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_q_W, ws.q, N);
1055	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_k_W, nullptr, ws.c_k, N, Nh);
1056	    sg2_stage_compress<Dims, /*IsCsa=*/false>(ws.x_sorted, w.hca_v_W, nullptr, ws.c_v, N, Nh);
1057	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_k_W, ws.win_k, N);
1058	    sg2_stage_project<Dims>(ws.x_sorted, w.hca_v_W, ws.win_v, N);
1059	    __syncthreads();
1060	    sg2_stage_hca_attention<Dims>(ws.q, ws.c_k, ws.c_v, ws.win_k, ws.win_v,
1061	                                  ws.concat, N, Nh);
1062	    __syncthreads();
1063	    sg2_stage_out_proj<Dims>(ws.concat, w.hca_out_W, ws.hca_ctx, N);
1064	    __syncthreads();
1065	
1066	    // g_sorted/s_sorted are read by GRU+PEER as grad[perm[r]]/sharp[perm[r]].
1067	    // To avoid recomputing the perm gather inside two stages, materialize them
1068	    // once into ws.q[:,0] and ws.q[:,1] (q is free now — attention consumed it).
1069	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1070	        const int src = perm[r];
1071	        float g = static_cast<float>(grad[src]);
1072	        float s = sharp[src];
1073	        if (!isfinite(g)) g = 0.0f;
1074	        if (!isfinite(s)) s = 0.0f;
1075	        ws.q[r * d + 0] = g;   // g_sorted
1076	        ws.q[r * d + 1] = s;   // s_sorted
1077	    }
1078	    __syncthreads();
1079	    // Strided views: g_sorted at stride d offset 0, s_sorted at stride d offset 1.
1080	    // The GRU/PEER stages take contiguous [N] g/s; build them into win_k[:,0]/
1081	    // win_k[:,1] contiguous? Simpler: pass strided access via small wrappers.
1082	    // We instead copy to contiguous front of win_k (free) and win_v (free).
1083	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
1084	        ws.win_k[r] = ws.q[r * d + 0];   // g_sorted contiguous
1085	        ws.win_v[r] = ws.q[r * d + 1];   // s_sorted contiguous
1086	    }
1087	    __syncthreads();
1088	    const float* g_sorted = ws.win_k;   // [N]
1089	    const float* s_sorted = ws.win_v;   // [N]
1090	
1091	    // S3: matrix-GRU forward (writes new_gru sorted + persists gru_state).
1092	    sg2_stage_gru<Dims>(w, g_sorted, s_sorted, ws.csa_ctx, ws.hca_ctx,
1093	                        perm, gru_state, ws.new_gru, N);
1094	    __syncthreads();
1095	
1096	    // S4: PEER routing + experts → expert_out (sorted), scaled by rescale.
1097	    sg2_stage_peer<Dims>(w, ws.new_gru, ws.csa_ctx, ws.hca_ctx,
1098	                         g_sorted, s_sorted, ws.expert_out, sc.rescale, N);
1099	    __syncthreads();
1100	
1101	    // S5: unsort + sg2_apply_step (canonical math).
1102	    sg2_stage_apply<Dims>(
1103	        param, exp_avg, exp_avg_sq, mu, slow, grad, ws.expert_out, unsort,
1104	        sc.alpha[tid], sc.gru_decay[tid], sc.lamb_eff[tid],
1105	        sc.lr, sc.beta1[tid], sc.beta2, sc.eps, sc.wd,
1106	        sc.bc1[tid], sc.bc2[tid], N);
1107	    __syncthreads();
1108	}
