1157	// =====================================================================
1158	//  Host launcher — one persistent CTA per SM, SG_TUNED_MEGA_BLOCK thr/CTA.
1159	//  Mirrors launch_fused_decoder_megakernel's hang-freedom contract:
1160	//  occupancy>=1 or refuse (the GridBarrier rendezvous of n_ctas CTAs can
1161	//  never complete if a CTA cannot be placed). Zeroes the barrier+queue
1162	//  counters per launch. The caller allocates the workspace + index buffers
1163	//  and PRE-COMPUTES perm/unsort (the one explicit pre-kernel sort step).
1164	// =====================================================================
1165	template <typename Dims, typename ParamT, typename GradT>
1166	cudaError_t launch_sg2_meta_optimizer_tail(
1167	    PersistentContext ctx,
1168	    SG2Weights w, SG2State st, SG2Scalars sc,
1169	    ParamT* params, const GradT* grads, const float* sharpness,
1170	    cudaStream_t stream) {
1171	    int dev = 0;
1172	    cudaError_t err = cudaGetDevice(&dev);
1173	    if (err != cudaSuccess) return err;
1174	    int n_sms = 0;
1175	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1176	    if (err != cudaSuccess) return err;
1177	
1178	    int occ = 0;
1179	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1180	        &occ, (const void*)&sg2_meta_optimizer_megakernel<Dims, ParamT, GradT>,
1181	        SG_TUNED_MEGA_BLOCK, /*dynamicSMemBytes=*/0);
1182	    if (err != cudaSuccess) return err;
1183	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1184	
1185	    const unsigned launch_ctas = (unsigned)n_sms;
1186	    ctx.n_ctas = launch_ctas;
1187	    ctx.n_tasks = st.n_tensors;
1188	
1189	    if (ctx.g_arrived)   { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1190	    if (ctx.g_generation){ err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1191	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1192	
1193	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
1194	    sg2_meta_optimizer_megakernel<Dims, ParamT, GradT><<<grid, block, 0, stream>>>(
1195	        ctx, w, st, sc, params, grads, sharpness);
1196	    return cudaGetLastError();
